def transforms(s):
 out=[]
 for refl in [False,True]:
  for rot in range(4):
   q=set()
   for r,c in s:
    if refl:c=-c
    for _ in range(rot): r,c=c,-r
    q.add((r,c))
   mr=min(x for x,y in q); mc=min(y for x,y in q)
   q=frozenset((x-mr,y-mc) for x,y in q)
   if q not in out:out.append(q)
 return out
