shapes

def occurrences(mat,shapes):
 H,W=mat.shape; found=[]
 for s in shapes:
  h=max(r for r,c in s)+1;w=max(c for r,c in s)+1
  for r in range(H-h+1):
   for c in range(W-w+1):
    pts={(r+dr,c+dc) for dr,dc in s}
    if all(mat[p]==0 for p in pts): found.append(pts)
 return found
